def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    opp_def = 0
    for _, o in history:
        if o == 'D':
            opp_def += 1

    # Against overwhelmingly defective opponents, always defect.
    if opp_def >= 7 and opp_def / n > 0.8:
        return 'D'

    last_my, last_opp = history[-1]

    # Late-game punishment for unprovoked defection.
    if n >= 90 and last_opp == 'D' and last_my == 'C':
        return 'D'

    if last_opp == 'D':
        if last_my == 'D':
            # We are in a mutual defection cycle. Try to recover unless opponent is very defective.
            if opp_def / n > 0.5:
                return 'D'
            return 'C'
        else:
            # We cooperated, opponent defected. Forgive unless it's a long streak.
            cd_streak = 0
            for i in range(n - 1, -1, -1):
                if history[i][0] == 'C' and history[i][1] == 'D':
                    cd_streak += 1
                else:
                    break
            if cd_streak >= 6:
                return 'D'
            return 'C'

    # If opponent cooperated, and we defected last round, return to cooperation.
    if last_my == 'D':
        return 'C'

    # Default: cooperate.
    return 'C'
